const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'package.json' -g '*ProfileSettings.tsx' -g '*Share*.tsx' -g '*ExternalLink*' -g '*strings*.json' | head -80",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"git status --short && ls -la .codex-role-output 2>/dev/null || true",workdir:"/app",max_output_tokens:3000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd; rg --files -g 'AGENTS.md' -g 'package.json' -g '*ProfileSettings.tsx' -g '*Share*.tsx' -g '*ExternalLink*' -g '*strings*.json' | head -80",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"git status --short; ls -la .codex-role-output 2>/dev/null || true",workdir:"/app",max_output_tokens:3000})
]);
results.forEach((result, i) => text(JSON.stringify({i, result})));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name ProfileSettings.tsx -o -name '*Share*.tsx' -o -name '*ExternalLink*' | head -100",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"ls -la | head -60; find . -maxdepth 3 -name package.json | head -30",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"find . -maxdepth 4 \\( -name 'en_EN.json' -o -name '*strings*.json' -o -name '*.scss' \\) | head -60",workdir:"/app",max_output_tokens:5000})
]);
results.forEach((result, i) => text(JSON.stringify({i, result})));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"find src/components/views/settings -maxdepth 2 -type f | sort | head -100; grep -RInE '<a([[:space:]>]|$)|target=\"_blank\"|external.link|external-link' src/components/views/settings --include='*.tsx' --include='*.ts' | head -220",workdir:"/app",max_output_tokens:15000}),
  tools.exec_command({cmd:"cat package.json | head -140; find test -iname '*Profile*' -o -iname '*Share*' -o -iname '*External*' | head -80",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"find res/img -maxdepth 1 -iname '*external*'; grep -RIn 'Link to room' src/i18n src/components test --exclude-dir=node_modules | head -50",workdir:"/app",max_output_tokens:3000})
]);
results.forEach((result,i)=>text(JSON.stringify({i,result})));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"find test -type f \\( -name '*Profile*' -o -name '*Share*' -o -name '*Link*' \\) | head -100; find src/components/views/elements -maxdepth 1 -type f | head -70",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"cat res/css/_components.scss | head -180; cat res/css/_font-sizes.scss | head -130; grep -RIn 'font-11px\\|font-3px\\|mask-image.*external' res/css --include='*.scss' | head -100",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"find src/components/views/settings -type f \\( -name '*.tsx' -o -name '*.ts' \\) -print0 | xargs -0 grep -nE 'href=|target=' | head -250",workdir:"/app",max_output_tokens:12000})
]);
results.forEach((result,i)=>text(JSON.stringify({i,result})));

