                    <AccessibleTooltipButton
                        title={_t("Copy")}
                        onClick={this.onCopyClick}
                        className="mx_ShareDialog_matrixto_copy"
                    />
                </div>
                { checkbox }
                { qrSocialSection }
            </div>
        </BaseDialog>;
    }
}
